/**
 * @summary List labs
 */
export const getListLabsUrl = (params?: ListLabsParams) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/labs?${stringifiedParams}`
    : `/api/labs`;
};

export const listLabs = async (
  params?: ListLabsParams,
  options?: RequestInit,
): Promise<Lab[]> => {
  return customFetch<Lab[]>(getListLabsUrl(params), {
    ...options,
    method: "GET",
  });
};

export const getListLabsQueryKey = (params?: ListLabsParams) => {
  return [`/api/labs`, ...(params ? [params] : [])] as const;
};

export const getListLabsQueryOptions = <
  TData = Awaited<ReturnType<typeof listLabs>>,
  TError = ErrorType<unknown>,
>(
  params?: ListLabsParams,
  options?: {
    query?: UseQueryOptions<
      Awaited<ReturnType<typeof listLabs>>,
      TError,
      TData
    >;
    request?: SecondParameter<typeof customFetch>;
  },
) => {
  const { query: queryOptions, request: requestOptions } = options ?? {};

  const queryKey = queryOptions?.queryKey ?? getListLabsQueryKey(params);

  const queryFn: QueryFunction<Awaited<ReturnType<typeof listLabs>>> = ({
    signal,
  }) => listLabs(params, { signal, ...requestOptions });

  return { queryKey, queryFn, ...queryOptions } as UseQueryOptions<
    Awaited<ReturnType<typeof listLabs>>,
    TError,
    TData
  > & { queryKey: QueryKey };
};

export type ListLabsQueryResult = NonNullable<
  Awaited<ReturnType<typeof listLabs>>
>;
export type ListLabsQueryError = ErrorType<unknown>;

